1	package stowage
2	
3	import (
4		"encoding/json"
5		"math"
6		"sort"
7		"strings"
8	)
9	
10	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
11	//
12	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
13	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
14	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
15	// 可以修正后重试。
16	//
17	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
18	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
19	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
20	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
21	// 范围也会被拒绝。
22	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
23		r.mu.Lock()
24		defer r.mu.Unlock()
25	
26		aid := strings.TrimSpace(adjustmentID)
27		if aid == "" {
28			return nil, fail(ErrInvalidID, "", "调整编号为空")
29		}
30	
31		// f 构造带调整编号的错误。
32		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
33			e := fail(kind, id, format, args...)
34			e.AdjustmentID = aid
35			return e
36		}
37	
38		// 幂等：编号已成功使用过。
39		if saved, ok := r.adjustments[aid]; ok {
40			if r.contents[aid] == canonicalKey(ops) {
41				return cloneResult(saved), nil
42			}
43			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
44		}
45	
46		if len(ops) == 0 {
47			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
48		}
49	
50		// 逐条校验操作。
51		seen := make(map[string]bool)
52		type validOp struct {
53			op     Op
54			cargo  *cargo
55			target *compartment // 装载/移动的目标舱位；卸下时为 nil
56		}
57		vops := make([]validOp, 0, len(ops))
58		affected := make(map[string]bool)
59	
60		for _, op := range ops {
61			cid := strings.TrimSpace(op.CargoID)
62			if cid == "" {
63				return nil, f(ErrInvalidID, "", "货物编号为空")
64			}
65			c, ok := r.cargos[cid]
66			if !ok {
67				return nil, f(ErrNotFound, cid, "货物 %s 不存在", cid)
68			}
69			if seen[cid] {
70				return nil, f(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
71			}
72			seen[cid] = true
73	
74			switch op.Kind {
75			case OpLoad:
76				if c.compartmentID != "" {
77					return nil, f(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
78				}
79				tid := strings.TrimSpace(op.Target)
80				if tid == "" {
81					return nil, f(ErrInvalidID, "", "目标舱位编号为空")
82				}
83				t, ok := r.compartments[tid]
84				if !ok {
85					return nil, f(ErrNotFound, tid, "舱位 %s 不存在", tid)
86				}
87				vops = append(vops, validOp{op, c, t})
88				affected[t.id] = true
89			case OpUnload:
90				if c.compartmentID == "" {
91					return nil, f(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
92				}
93				vops = append(vops, validOp{op, c, nil})
94				affected[c.compartmentID] = true
95			case OpMove:
96				if c.compartmentID == "" {
97					return nil, f(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
98				}
99				tid := strings.TrimSpace(op.Target)
100				if tid == "" {
101					return nil, f(ErrInvalidID, "", "目标舱位编号为空")
102				}
103				t, ok := r.compartments[tid]
104				if !ok {
105					return nil, f(ErrNotFound, tid, "舱位 %s 不存在", tid)
106				}
107				if t.id == c.compartmentID {
108					return nil, f(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
109				}
110				vops = append(vops, validOp{op, c, t})
111				affected[c.compartmentID] = true
112				affected[t.id] = true
113			default:
114				return nil, f(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
115			}
116		}
117	
118		// 在模拟配载上应用全部操作。
119		final := make(map[string]map[string]*cargo, len(r.compartments))
120		for id, comp := range r.compartments {
121			set := make(map[string]*cargo, len(comp.cargo))
122			for cid, c := range comp.cargo {
123				set[cid] = c
124			}
125			final[id] = set
126		}
127		for _, v := range vops {
128			switch v.op.Kind {
129			case OpLoad:
130				final[v.target.id][v.cargo.id] = v.cargo
131			case OpUnload:
132				delete(final[v.cargo.compartmentID], v.cargo.id)
133			case OpMove:
134				delete(final[v.cargo.compartmentID], v.cargo.id)
135				final[v.target.id][v.cargo.id] = v.cargo
136			}
137		}
138	
139		// 按最终配载校验承重与混装限制。
140		for id, set := range final {
141			var sum int64
142			destinations := make(map[string]bool)
143			for _, c := range set {
144				if c.weight > math.MaxInt64-sum {
145					return nil, f(ErrOverflow, id, "舱位 %s 重量合计超过 int64 可表示范围", id)
146				}
147				sum += c.weight
148				destinations[c.destination] = true
149			}
150			if sum > r.compartments[id].maxWeight {
151				return nil, f(ErrOverweight, id, "舱位 %s 总重量 %d 千克超过最大承重 %d 千克", id, sum, r.compartments[id].maxWeight)
152			}
153			if len(destinations) > 1 {
154				for _, c := range set {
155					if !c.allowMixed {
156						return nil, f(ErrMixedLoading, c.id, "舱位 %s 存在不同目的地货物，但货物 %s 不允许混装", id, c.id)
157					}
158				}
159			}
160		}
161	
162		// 全部合法，正式生效。先计算受影响舱位调整前后的重量。
163		cargoChanges := make([]CargoChange, 0, len(vops))
164		compChanges := make([]CompartmentChange, 0, len(affected))
165		for id := range affected {
166			compChanges = append(compChanges, CompartmentChange{
167				CompartmentID: id,
168				WeightBefore:  sumSet(r.compartments[id].cargo),
169				WeightAfter:   sumSet(final[id]),
170			})
171		}
172		sort.Slice(compChanges, func(i, j int) bool {
173			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
174		})
175	
176		for _, v := range vops {
177			c := v.cargo
178			from := c.compartmentID
179			var to string
180			switch v.op.Kind {
181			case OpLoad:
182				r.compartments[v.target.id].cargo[c.id] = c
183				c.compartmentID = v.target.id
184				to = v.target.id
185			case OpUnload:
186				delete(r.compartments[from].cargo, c.id)
187				c.compartmentID = ""
188			case OpMove:
189				delete(r.compartments[from].cargo, c.id)
190				r.compartments[v.target.id].cargo[c.id] = c
191				c.compartmentID = v.target.id
192				to = v.target.id
193			}
194			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
195		}
196		sort.Slice(cargoChanges, func(i, j int) bool {
197			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
198		})
199	
200		result := &AdjustmentResult{
201			ID:                 aid,
202			CargoChanges:       cargoChanges,
203			CompartmentChanges: compChanges,
204		}
205		r.adjustments[aid] = result
206		r.contents[aid] = canonicalKey(ops)
207		return cloneResult(result), nil
208	}
209	
210	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
211	// 即视为相同内容，排列顺序不影响判断。
212	func canonicalKey(ops []Op) string {
213		sorted := make([]Op, len(ops))
214		for i, op := range ops {
215			sorted[i] = Op{
216				Kind:    op.Kind,
217				CargoID: strings.TrimSpace(op.CargoID),
218				Target:  strings.TrimSpace(op.Target),
219			}
220		}
221		sort.Slice(sorted, func(i, j int) bool {
222			if sorted[i].Kind != sorted[j].Kind {
223				return sorted[i].Kind < sorted[j].Kind
224			}
225			if sorted[i].CargoID != sorted[j].CargoID {
226				return sorted[i].CargoID < sorted[j].CargoID
227			}
228			return sorted[i].Target < sorted[j].Target
229		})
230		b, err := json.Marshal(sorted)
231		if err != nil {
232			// Op 仅含基本类型，不会失败。
233			panic(err)
234		}
235		return string(b)
236	}
