9	// requireError 断言 err 是 *Error 且 Kind 匹配。
10	func requireError(t *testing.T, err error, kind ErrorKind) *Error {
11		t.Helper()
12		if err == nil {
13			t.Fatalf("期望错误 %s，实际为 nil", kind)
14		}
15		var se *Error
16		if !errors.As(err, &se) {
17			t.Fatalf("期望 *Error，实际为 %T: %v", err, err)
18		}
19		if se.Kind != kind {
20			t.Fatalf("期望错误 %s，实际为 %s（%v）", kind, se.Kind, err)
21		}
22		return se
23	}
24	
25	// ---------- 登记 ----------
26	
27	func TestRegisterCompartmentSuccess(t *testing.T) {
28		r := NewRegistry()
29		if err := r.RegisterCompartment("  C1  ", 100); err != nil {
30			t.Fatal(err)
31		}
32		view, err := r.Compartment("C1")
33		if err != nil {
34			t.Fatal(err)
35		}
36		if view.MaxWeight != 100 || view.UsedWeight != 0 || view.RemainingWeight != 100 {
37			t.Fatalf("舱位初始状态错误: %+v", view)
38		}
39		if len(view.Cargo) != 0 {
40			t.Fatalf("新舱位不应有货物: %+v", view.Cargo)
41		}
42	}
43	
44	func TestRegisterCompartmentInvalid(t *testing.T) {
45		r := NewRegistry()
46		for _, id := range []string{"", "   ", "\t\n"} {
47			requireError(t, r.RegisterCompartment(id, 100), ErrInvalidID)
48		}
49		for _, w := range []int64{0, -1, -100} {
50			requireError(t, r.RegisterCompartment("C1", w), ErrInvalidWeight)
51		}
52	}
53	
54	func TestRegisterCompartmentDuplicate(t *testing.T) {
55		r := NewRegistry()
56		if err := r.RegisterCompartment("C1", 100); err != nil {
57			t.Fatal(err)
58		}
59		err := r.RegisterCompartment("C1", 200)
60		se := requireError(t, err, ErrAlreadyExists)
61		if se.ID != "C1" {
62			t.Fatalf("重复登记错误应指出舱位编号，实际 ID=%q", se.ID)
63		}
64		// 原记录保留。
65		view, _ := r.Compartment("C1")
66		if view.MaxWeight != 100 {
67			t.Fatalf("重复登记后原记录被改变: %+v", view)
68		}
69	}
